<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life ✨</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: radial-gradient(1200px 800px at 50% -10%, #1b2450 0%, #0b0e1a 55%, #060812 100%);
    color: #e8ecff;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
  }
  .wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
    width: 100%;
    max-width: 640px;
  }
  h1 {
    margin: 0;
    font-size: 28px;
    letter-spacing: 0.5px;
    text-align: center;
    text-shadow: 0 0 18px #00ffcc88, 0 0 40px #7c5cff66;
  }
  h1 .sub {
    display: block;
    font-size: 14px;
    font-weight: 500;
    opacity: 0.8;
    margin-top: 4px;
    text-shadow: none;
  }
  .stats {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
    font-size: 14px;
  }
  .pill {
    background: #151b33;
    border: 1px solid #2a3566;
    padding: 6px 14px;
    border-radius: 999px;
    box-shadow: inset 0 0 12px #00000066;
  }
  .pill b { color: #00ffcc; }
  #life {
    width: 500px;
    height: 500px;
    min-width: 400px;
    min-height: 400px;
    border-radius: 16px;
    border: 2px solid #2de1c2;
    box-shadow: 0 0 0 4px #141a35, 0 0 25px #00ffcc66, 0 0 80px #7c5cff44, 0 12px 40px #000000aa;
    background: #070b18;
    cursor: crosshair;
    touch-action: none;
    display: block;
  }
  .controls {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    font-size: 16px;
    font-weight: 800;
    color: #0b0e1a;
    border: none;
    border-radius: 999px;
    padding: 11px 20px;
    cursor: pointer;
    transition: transform 0.08s ease, filter 0.15s ease;
    box-shadow: 0 4px 0 #00000055, 0 6px 18px #00000066;
  }
  button:hover { transform: translateY(-2px) scale(1.03); filter: brightness(1.08); }
  button:active { transform: translateY(1px) scale(0.98); }
  #step { background: linear-gradient(135deg, #ffe45e, #ff9a3d); }
  #play { background: linear-gradient(135deg, #00ffcc, #00a8ff); min-width: 130px; }
  #random { background: linear-gradient(135deg, #c792ff, #ff6ad5); }
  #clear { background: linear-gradient(135deg, #ff6b6b, #ff2e88); color: #fff; }
  .hint {
    font-size: 13px;
    opacity: 0.75;
    text-align: center;
  }
  .speed { display:flex; align-items:center; gap:8px; font-size:13px; opacity:0.9; }
  input[type="range"] { accent-color: #00ffcc; }
</style>
</head>
<body>
<div class="wrap">
  <h1>🧬 Conway's Game of Life 🎮<span class="sub">B3 / S23 • dead edges • simultaneous updates ✨</span></h1>
  <div class="stats">
    <div class="pill">Generation: <b id="gen">0</b></div>
    <div class="pill">Population: <b id="pop">0</b></div>
    <div class="pill">Grid: <b id="size">50×50</b></div>
  </div>
  <canvas id="life"></canvas>
  <div class="controls">
    <button id="step" title="Advance one generation">👣 Step</button>
    <button id="play" title="Toggle auto-run">▶️ Play</button>
    <button id="random" title="Seed random cells">🎲 Random</button>
    <button id="clear" title="Kill all cells">🧹 Clear</button>
  </div>
  <div class="speed">⚡ speed <input id="speed" type="range" min="30" max="500" value="120" step="10"> <span id="speedLabel">120ms</span></div>
  <div class="hint">🖱️ Click or drag on the grid to paint cells alive / dead • Try a glider gun! 🚀</div>
</div>
<script>
(function() {
  var W = 50, H = 50;
  var CSS = 500;
  var canvas = document.getElementById('life');
  var ctx = canvas.getContext('2d');
  var genEl = document.getElementById('gen');
  var popEl = document.getElementById('pop');
  var grid = new Uint8Array(W * H);
  var generation = 0;
  var speedMs = 120;

  canvas.style.width = CSS + 'px';
  canvas.style.height = CSS + 'px';

  function setupBacking() {
    var dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(CSS * dpr);
    canvas.height = Math.round(CSS * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  setupBacking();
  window.addEventListener('resize', function() { setupBacking(); draw(); });

  function idx(x, y) { return y * W + x; }

  function getCell(x, y) {
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= W || y >= H) return 0;
    return grid[idx(x, y)] ? 1 : 0;
  }

  function setCell(x, y, v) {
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    grid[idx(x, y)] = v ? 1 : 0;
    draw();
    updateStats();
  }

  function stepOnce() {
    var next = new Uint8Array(W * H);
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        var n = 0;
        for (var dy = -1; dy <= 1; dy++) {
          for (var dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            var nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
              n += grid[ny * W + nx];
            }
          }
        }
        var alive = grid[y * W + x] === 1;
        var out = 0;
        if (alive) {
          out = (n === 2 || n === 3) ? 1 : 0;
        } else {
          out = (n === 3) ? 1 : 0;
        }
        next[y * W + x] = out;
      }
    }
    grid = next;
    generation++;
    draw();
    updateStats();
  }

  function clearAll() {
    grid = new Uint8Array(W * H);
    generation = 0;
    draw();
    updateStats();
  }

  function randomize(density) {
    density = density || 0.22;
    for (var i = 0; i < grid.length; i++) {
      grid[i] = Math.random() < density ? 1 : 0;
    }
    generation = 0;
    draw();
    updateStats();
  }

  function updateStats() {
    var pop = 0;
    for (var i = 0; i < grid.length; i++) pop += grid[i];
    genEl.textContent = generation;
    popEl.textContent = pop;
  }

  function draw() {
    var cw = CSS / W, ch = CSS / H;
    // background
    ctx.fillStyle = '#070b18';
    ctx.fillRect(0, 0, CSS, CSS);

    // subtle checker for dead cells
    ctx.fillStyle = '#0c1228';
    var checker = 1;
    // live cells with neon glow
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        if (grid[y * W + x]) {
          var px = x * cw, py = y * ch;
          var hue = (x * 4 + y * 4 + generation * 3) % 360;
          // glow body
          ctx.fillStyle = 'hsl(' + (160 + (hue % 60)) + ', 100%, 60%)';
          ctx.shadowColor = '#00ffcc';
          ctx.shadowBlur = 10;
          var pad = 0.8;
          roundRect(px + pad, py + pad, cw - pad * 2, ch - pad * 2, 2.5);
          ctx.fill();
          ctx.shadowBlur = 0;
          // highlight dot
          ctx.fillStyle = 'rgba(255,255,255,0.55)';
          ctx.fillRect(px + cw * 0.3, py + ch * 0.3, cw * 0.22, ch * 0.22);
        }
      }
    }
    ctx.shadowBlur = 0;

    // grid lines
    ctx.strokeStyle = 'rgba(120,140,255,0.12)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var gx = 0; gx <= W; gx++) {
      var lx = Math.round(gx * cw) + 0.5;
      ctx.moveTo(lx, 0);
      ctx.lineTo(lx, CSS);
    }
    for (var gy = 0; gy <= H; gy++) {
      var ly = Math.round(gy * ch) + 0.5;
      ctx.moveTo(0, ly);
      ctx.lineTo(CSS, ly);
    }
    ctx.stroke();
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  // Expose required API
  window.life = {
    w: W,
    h: H,
    get: getCell,
    set: setCell,
    step: stepOnce,
    clear: clearAll
  };

  // Buttons
  document.getElementById('step').addEventListener('click', function() { stepOnce(); });
  document.getElementById('clear').addEventListener('click', function() { clearAll(); });
  document.getElementById('random').addEventListener('click', function() { randomize(0.22); });

  var playBtn = document.getElementById('play');
  var timer = null, playing = false;
  function setPlaying(p) {
    playing = p;
    if (timer) { clearInterval(timer); timer = null; }
    if (playing) { timer = setInterval(stepOnce, speedMs); playBtn.textContent = '⏸️ Pause'; }
    else { playBtn.textContent = '▶️ Play'; }
  }
  playBtn.addEventListener('click', function() { setPlaying(!playing); });

  var speedInput = document.getElementById('speed');
  var speedLabel = document.getElementById('speedLabel');
  speedInput.addEventListener('input', function() {
    speedMs = parseInt(speedInput.value, 10);
    speedLabel.textContent = speedMs + 'ms';
    if (playing) { clearInterval(timer); timer = setInterval(stepOnce, speedMs); }
  });

  // Painting: click / drag toggles cells (paint alive/dead based on first cell)
  var painting = false;
  var paintValue = 1;

  function eventToCell(e) {
    var rect = canvas.getBoundingClientRect();
    var fx = (e.clientX - rect.left) / rect.width;
    var fy = (e.clientY - rect.top) / rect.height;
    var x = Math.floor(fx * W);
    var y = Math.floor(fy * H);
    if (x < 0) x = 0; if (y < 0) y = 0;
    if (x >= W) x = W - 1; if (y >= H) y = H - 1;
    return { x: x, y: y };
  }

  canvas.addEventListener('pointerdown', function(e) {
    e.preventDefault();
    var c = eventToCell(e);
    paintValue = getCell(c.x, c.y) ? 0 : 1;
    painting = true;
    try { canvas.setPointerCapture(e.pointerId); } catch (err) {}
    // set without extra draw storm: direct write then draw once
    grid[idx(c.x, c.y)] = paintValue ? 1 : 0;
    draw(); updateStats();
  });
  canvas.addEventListener('pointermove', function(e) {
    if (!painting) return;
    e.preventDefault();
    var c = eventToCell(e);
    if (grid[idx(c.x, c.y)] !== paintValue) {
      grid[idx(c.x, c.y)] = paintValue ? 1 : 0;
      draw(); updateStats();
    }
  });
  function endPaint(e) { painting = false; }
  canvas.addEventListener('pointerup', endPaint);
  canvas.addEventListener('pointercancel', endPaint);
  canvas.addEventListener('pointerleave', function(e) {
    // keep painting if pointer captured; otherwise stop when leaving without buttons
    if (e.buttons === 0) painting = false;
  });

  // Fun initial soup + a glider for instant delight
  randomize(0.18);
  // stamp a glider near top-left so users see motion
  (function stampGlider(ox, oy) {
    var cells = [[1,0],[2,1],[0,2],[1,2],[2,2]];
    for (var i = 0; i < cells.length; i++) {
      var x = ox + cells[i][0], y = oy + cells[i][1];
      if (x >= 0 && y >= 0 && x < W && y < H) grid[y * W + x] = 1;
    }
    draw(); updateStats();
  })(5, 5);
})();
</script>
</body>
</html>
